/* Auto-generated from client/public/*.png for server-side PDF generation. */

export type InvoiceLogoBrand = 'BAS' | 'BFS' | 'GSEC';

const BAS_PNG_BASE64 = "";

const BFS_PNG_BASE64 = "";

const GSEC_PNG_BASE64 = "";

const LOGO_BASE64: Record<InvoiceLogoBrand, string> = {
  BAS: BAS_PNG_BASE64,
  BFS: BFS_PNG_BASE64,
  GSEC: GSEC_PNG_BASE64,
};

export function getInvoiceLogoBuffer(brand: InvoiceLogoBrand): Buffer {
  return Buffer.from(LOGO_BASE64[brand] ?? LOGO_BASE64.BAS, 'base64');
}
